class Solution {
public:
    int numIdenticalPairs(vector<int>& nums) {
        int count[101] = {0};
        for (int x : nums) count[x]++;
        int ans = 0;
        for (int i = 1; i <= 100; i++) {
            ans += count[i] * (count[i] - 1) / 2;
        }
        return ans;
    }
};
